-- ============================================================
-- SEED EXT 2: Módulo 24 — Discourse Markers (exercícios 71-185)
-- Novos tópicos: posição dos marcadores, concessão vs contraste,
-- marcadores de atribuição, hedging markers, síntese avançada
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'discourse-markers';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo discourse-markers não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 11: posição dos marcadores (pontuação e posição)
  (cid,11,71,'multiple_choice','Which sentence has CORRECT punctuation for a sentence connector?','The data were inconclusive; consequently, the study was extended.','["The data were inconclusive, consequently the study was extended.","The data were inconclusive consequently, the study was extended.","The data were inconclusive; consequently, the study was extended.","The data were inconclusive; consequently the study was extended."]','Semicolon before connector + comma after = correct for sentence adverbials.','hard'),
  (cid,11,72,'gap_fill','___, the findings were significant. ___, the sample was too small to generalize. (addition + concession)','Moreover / However',NULL,'Moreover (addition) + However (contrast/concession) as sentence-initial connectors.','medium'),
  (cid,11,73,'multiple_choice','Where can "however" appear in a sentence?','At the beginning, after a semicolon mid-sentence, or after the subject.','["Only at the beginning of a sentence","Only after a semicolon","At the beginning, after a semicolon mid-sentence, or after the subject.","Only at the end of a sentence"]','"However" is flexible: "However, X" / "X; however, Y" / "X. Y, however, Z."','hard'),
  (cid,11,74,'gap_fill','The results were consistent with the hypothesis. The sample size, ___, was too small for definitive conclusions.','however',NULL,'"However" after the subject (mid-sentence position) adds contrast.','hard'),
  (cid,11,75,'multiple_choice','Which sentence uses "therefore" in the CORRECT mid-sentence position?','The funding was cut; the project, therefore, was terminated.','["The funding was cut; the project was, therefore terminated.","The funding was cut; the project, therefore, was terminated.","The funding was cut; therefore the project was terminated (needs comma after therefore).","The funding was cut, the project therefore was terminated (comma splice)."]','Semicolon + subject + therefore + comma = correct embedded connector position.','hard'),
  (cid,11,76,'gap_fill','The study had limitations. ___ ___, these do not undermine its core findings.','That said / Nevertheless / Even so',NULL,'Concessive connector after a period = sentence-initial with comma after.','medium'),
  (cid,11,77,'multiple_choice','Which pair shows INCORRECT connector positioning?','"The data, moreover, supports the claim. / The data however supports the claim."','["However, the data supports the claim. / The data, however, supports the claim.","The data supports the claim; nevertheless, more research is needed. / Nevertheless, more research is needed.","The data, moreover, supports the claim. / The data however supports the claim.","Consequently, the study was extended. / The study was, consequently, extended."]','"The data however supports the claim" is missing commas around "however."','hard'),

  -- BLOCK 12: concessão vs contraste — distinções finas
  (cid,12,78,'multiple_choice','What is the functional difference between "although" and "nevertheless"?','Although introduces a concessive clause; nevertheless connects two separate sentences.','["They are identical in meaning and use","Although introduces a concessive clause; nevertheless connects two separate sentences.","Nevertheless is more formal than although","Although can only start a sentence; nevertheless cannot"]','"Although" = subordinating conjunction (clause). "Nevertheless" = sentence adverbial (after a full stop or semicolon).','hard'),
  (cid,12,79,'gap_fill','___ the limitations are significant, the study contributes meaningfully to the field.','Although / Even though / While',NULL,'Subordinating conjunction + clause: Although/Even though + clause, main clause.','medium'),
  (cid,12,80,'multiple_choice','Which sentence pair uses BOTH contrast and concession correctly?','Although the results were unexpected, they were reliable. Nevertheless, the team decided to replicate the study.','["However the results were unexpected, they were reliable. Although, the team replicated the study.","Although the results were unexpected, they were reliable. Nevertheless, the team decided to replicate the study.","The results were unexpected although. Nevertheless the team replicated the study.","Although the results were unexpected. Nevertheless they were reliable."]','Although (clause) + Nevertheless (new sentence connector).','hard'),
  (cid,12,81,'gap_fill','Group A improved significantly. ___, Group B showed almost no change.','In contrast / By contrast / Conversely',NULL,'"In contrast" for a sharp difference between two groups — sentence connector.','medium'),
  (cid,12,82,'multiple_choice','Which marker introduces a STRONG CONTRAST with the previous sentence?','On the contrary','["Moreover","Furthermore","On the contrary","Additionally"]','"On the contrary" = strong direct opposition ("not X — in fact the opposite").','hard'),
  (cid,12,83,'gap_fill','The traditional method is cost-effective. The new method, ___, is faster but more expensive.','by contrast / however / on the other hand',NULL,'Mid-sentence contrast connector after the subject.','medium'),
  (cid,12,84,'multiple_choice','Choose the sentence that INCORRECTLY uses "on the contrary":','The results were positive. On the contrary, the team celebrated.','["The study did not fail. On the contrary, it was a groundbreaking success.","She is not unintelligent. On the contrary, she is exceptionally gifted.","The results were positive. On the contrary, the team celebrated.","The policy was not ineffective. On the contrary, it exceeded all targets."]','"On the contrary" corrects a negative — team celebrating after positive results is not a contrast.','hard'),

  -- BLOCK 13: marcadores de atribuição e citação acadêmica
  (cid,13,85,'gap_fill','___ (according to) Smith (2020), the relationship between income and health is well established.','According to',NULL,'"According to + source" = attribution marker for reported information.','easy'),
  (cid,13,86,'multiple_choice','Which attribution marker is most common in academic writing?','As noted by','["You know, according to","As noted by","Like Jones says","The way Smith sees it"]','"As noted by" = formal academic attribution marker.','medium'),
  (cid,13,87,'gap_fill','___ (as argued by) Jones (2019), traditional curricula are ill-equipped for 21st-century demands.','As argued by',NULL,'"As argued by + author" introduces a cited position.','medium'),
  (cid,13,88,'multiple_choice','Which phrase introduces a contrasting cited view in academic writing?','In contrast, Brown (2021) maintains that...','["Also, Brown (2021) says...","In contrast, Brown (2021) maintains that...","But Brown (2021) thinks...","And Brown (2021) goes on to say..."]','"In contrast, [Author] maintains" = contrasting citation in formal academic register.','hard'),
  (cid,13,89,'gap_fill','___ ___ (as suggested by) recent meta-analyses, the effect size is modest.','As suggested by',NULL,'"As suggested by" for citing collective or recent evidence.','medium'),
  (cid,13,90,'multiple_choice','Which marker correctly signals that the author is about to DISAGREE with a cited view?','However, this view has been challenged by...','["Furthermore, this view has been challenged by...","However, this view has been challenged by...","In addition, this view has been challenged by...","As a result, this view has been challenged by..."]','"However" signals the pivot from cited view to the author''s counter-argument.','medium'),
  (cid,13,91,'gap_fill','The evidence is compelling. ___ ___ (it is worth noting that), some studies have reported conflicting results.','It is worth noting that',NULL,'"It is worth noting that" = hedged academic attention marker.','hard'),

  -- BLOCK 14: hedging discourse markers
  (cid,14,92,'multiple_choice','Which phrase is a HEDGING discourse marker?','It would appear that','["It is proven that","It would appear that","It is a fact that","It is certain that"]','"It would appear that" = hedged claim — not stating certainty.','hard'),
  (cid,14,93,'gap_fill','___ ___ (arguably), this represents the most significant finding in the field in recent years.','Arguably',NULL,'"Arguably" = academic hedge: one could argue that; it can be maintained that.','hard'),
  (cid,14,94,'multiple_choice','Which hedging marker is appropriate in a TOEFL essay conclusion?','It may be argued that further research is needed to substantiate these claims.','["It is proven that further research is needed.","It may be argued that further research is needed to substantiate these claims.","Everyone knows that further research is needed.","Obviously, further research is needed."]','"It may be argued that" = appropriately hedged TOEFL conclusion.','hard'),
  (cid,14,95,'gap_fill','___ at first sight, the data appear contradictory; however, closer analysis reveals a consistent pattern.','At first sight / On the surface / Seemingly',NULL,'Hedging marker acknowledging apparent contradiction before explaining it.','hard'),
  (cid,14,96,'multiple_choice','Which phrase introduces a TENTATIVE CLAIM?','It seems plausible that increased investment leads to better outcomes.','["It is obvious that increased investment leads to better outcomes.","It seems plausible that increased investment leads to better outcomes.","Everyone agrees that increased investment leads to better outcomes.","It is proven that increased investment leads to better outcomes."]','"It seems plausible that" = hedged, tentative claim appropriate in academic writing.','hard'),
  (cid,14,97,'gap_fill','___ ___ (it should be noted that), this finding is based on a relatively small sample and requires further verification.','It should be noted that',NULL,'Academic disclaimer marker before acknowledging a limitation.','medium'),
  (cid,14,98,'multiple_choice','Which hedging marker OVERQUALIFIES and weakens an academic argument?','It could perhaps possibly be somewhat argued that...','["It may be argued that...","It has been suggested that...","It would appear that...","It could perhaps possibly be somewhat argued that..."]','Over-hedging weakens credibility — one clear hedge is sufficient.','hard'),

  -- BLOCK 15: marcadores de sequência em textos complexos
  (cid,15,99,'gap_fill','The study proceeded in three phases. ___ (first phase marker), data were collected. ___ (second marker), they were coded. ___ (final marker), findings were written up.','Initially / Subsequently / Finally',NULL,'Academic sequence: Initially → Subsequently → Finally.','medium'),
  (cid,15,100,'multiple_choice','Which set of sequence markers is MOST appropriate for academic writing?','Initially... Subsequently... Finally...','["First of all... Then... And then... At the end...","Initially... Subsequently... Finally...","Firstly... Next... Lastly...","To start with... After that... To finish..."]','"Initially / Subsequently / Finally" = highest register for academic sequencing.','hard'),
  (cid,15,101,'gap_fill','The hypothesis was first tested qualitatively. ___ (later), a quantitative component was added.','Subsequently / Later / Thereafter',NULL,'"Subsequently" = formal time-sequence marker.','medium'),
  (cid,15,102,'multiple_choice','What does "henceforth" signal in academic writing?','From this point in the text/time onwards.','["Up until this point","Because of this","From this point in the text/time onwards.","In contrast to this"]','"Henceforth" = from this point forward (formal temporal/textual marker).','hard'),
  (cid,15,103,'gap_fill','The variable will ___ (henceforth) be referred to as "the treatment effect."','henceforth',NULL,'"Henceforth" = from now on in this text.','hard'),
  (cid,15,104,'multiple_choice','Which marker signals that the writer is returning to an earlier point?','As mentioned previously','["As a result","As mentioned previously","For instance","In contrast"]','"As mentioned previously" = backward reference / anaphoric marker.','medium'),

  -- BLOCK 16: TOEFL Reading — marcadores avançados
  (cid,16,105,'multiple_choice','[TOEFL Reading] "The ancient Greeks believed the Earth was at the center of the universe. Subsequently, Copernicus demonstrated that the Earth orbits the Sun." "Subsequently" signals:','A later development that replaced the earlier belief.','["A contrast with the Greek view","An addition to the Greek view","A later development that replaced the earlier belief.","A concession about the Greek view"]','"Subsequently" = time sequence — something happened after and as a result.','medium'),
  (cid,16,106,'gap_fill','[TOEFL Reading] "The initial results were promising. ___ closer examination, however, revealed significant methodological flaws." Best marker?','Subsequent / Further',NULL,'"Subsequent/Further examination" = reference to a later stage of analysis.','hard'),
  (cid,16,107,'multiple_choice','[TOEFL Reading] "It has been argued that economic growth is incompatible with environmental sustainability. This view, however, has been increasingly challenged." The phrase "this view, however" does what?','Signals that the author is about to contest the previously stated position.','["Adds more evidence for the first claim","Gives an example of economic growth","Signals that the author is about to contest the previously stated position.","Summarizes the argument"]','"However" + anaphoric reference ("this view") = pivot to counterargument.','hard'),
  (cid,16,108,'gap_fill','[TOEFL Reading] "The policy was introduced in 2010. ___ (by 2015), it had transformed the sector." Best marker?','By 2015 / Within five years / Subsequently',NULL,'Time marker indicating completion within a period.','medium'),
  (cid,16,109,'multiple_choice','[TOEFL Reading] "Admittedly, the study has limitations. Nevertheless, it represents the most comprehensive analysis to date." The two markers work together to:','Concede a weakness and then assert a stronger compensating merit.','["Add two positive points","Contrast two unrelated ideas","Concede a weakness and then assert a stronger compensating merit.","Summarize the main argument"]','Admittedly (concede) + Nevertheless (but here is the stronger point).','hard'),
  (cid,16,110,'gap_fill','[TOEFL Reading] "Deforestation has increased significantly. ___, biodiversity loss has accelerated." Best marker?','Consequently / As a result / Accordingly',NULL,'Cause-effect: deforestation → biodiversity loss.','easy'),

  -- BLOCK 17: TOEFL Listening — marcadores em contexto oral acadêmico
  (cid,17,111,'multiple_choice','[TOEFL Listening] A professor says: "So, to recap what we''ve covered today..." This phrase signals:','A summary of the lecture''s main points.','["A new topic is being introduced","A contrast is being made","A summary of the lecture''s main points.","An example is being given"]','"To recap" = summary marker, equivalent to "In summary."','easy'),
  (cid,17,112,'gap_fill','[TOEFL Listening] "Let''s return ___ the issue of funding." Best marker?','to',NULL,'"Let''s return to" = topic return marker (spoken academic).','easy'),
  (cid,17,113,'multiple_choice','[TOEFL Listening] A professor says: "Now, this brings me to my second point." This marker:','Signals a transition to the next point in a structured argument.','["Introduces an example","Summarizes the previous point","Signals a transition to the next point in a structured argument.","Introduces a contrasting idea"]','"This brings me to" = spoken discourse transition marker.','medium'),
  (cid,17,114,'gap_fill','[TOEFL Listening] "What I mean ___ ___ (by this) is that correlation does not imply causation." Best phrase?','by this',NULL,'"What I mean by this is that" = clarification/reformulation marker in spoken academic English.','hard'),
  (cid,17,115,'multiple_choice','[TOEFL Listening] "Interestingly, participants who exercised regularly showed no improvement." The marker "interestingly" signals:','The speaker finds this result surprising or noteworthy.','["The speaker is certain about this result","The speaker dismisses this result","The speaker finds this result surprising or noteworthy.","The speaker agrees with previous research"]','"Interestingly" = attention-focusing evaluative marker highlighting a surprising finding.','medium'),

  -- BLOCK 18: TOEFL Speaking production
  (cid,18,116,'production','[TOEFL Speaking — 45s] Using discourse markers only (no content filler), organize a 45-second argument for or against mandatory military service. Include: firstly, furthermore, however, that said, and in conclusion.','',NULL,'Firstly, mandatory service builds discipline... Furthermore, it fosters national unity... However, it restricts individual freedom... That said, volunteer models often fail to meet defense needs... In conclusion, a balanced hybrid system may offer the best solution.','hard'),
  (cid,18,117,'production','[TOEFL Speaking — 45s] You read that urban green spaces improve mental health. Summarize the argument and challenge it using: according to, however, it is worth noting that, admittedly, consequently.','',NULL,'According to recent studies, access to green spaces significantly reduces stress... However, not all urban residents have equal access to parks... Admittedly, the correlation is strong. It is worth noting that confounding factors such as income may explain the findings. Consequently, policy must address access equity alongside green space provision.','hard'),
  (cid,18,118,'production','[TOEFL Speaking — 45s] A lecture discusses the pros and cons of open-source technology. Report both sides and give a conclusion. Use: on the one hand / on the other hand / it may be argued / subsequently / in conclusion.','',NULL,'On the one hand, open-source technology democratizes access to powerful tools. On the other hand, it may lack the security controls of proprietary software. It may be argued that the collaborative model of open source leads to faster innovation. Subsequently, many enterprises have adopted hybrid models. In conclusion, the benefits of open source likely outweigh the risks when proper governance is in place.','hard'),

  -- BLOCK 19: TOEFL Writing production
  (cid,19,119,'production','[TOEFL Writing] Fix all discourse marker errors in this paragraph: "The results were significant. Despite, there were limitations. Also furthermore, a larger study is recommended. So in conclusion, the findings are valuable but incomplete."','',NULL,'Despite → Nevertheless / However; Also furthermore → choose one (Moreover / Furthermore); So in conclusion → In conclusion (remove "so").','hard'),
  (cid,19,120,'production','[TOEFL Writing — 200 words] Write a full TOEFL body paragraph on the topic "Should universities prioritize STEM over humanities?" Use discourse markers from AT LEAST 5 different categories: addition, contrast, concession, cause-effect, attribution, and hedging. Underline each marker.','',NULL,'It may be argued that the growing demand for technological skills justifies increased investment in STEM disciplines. Furthermore, graduates in engineering and computer science consistently earn higher starting salaries, which makes a compelling economic case. As noted by the World Economic Forum (2023), digital literacy will be essential for 85% of future jobs. Nevertheless, this view has been challenged by educators who maintain that critical thinking and communication — skills developed through the humanities — are equally essential for leadership roles. In contrast to purely vocational approaches, a liberal arts education fosters adaptability, which is arguably the most valuable skill in a rapidly changing economy. Admittedly, resource constraints force institutions to make difficult prioritization decisions. Consequently, it would appear that the most effective strategy is integration rather than opposition: universities that embed data literacy within humanities programs, for instance, may produce graduates uniquely equipped for interdisciplinary challenges. In conclusion, the framing of STEM versus humanities may itself be a false dichotomy.','hard'),

  -- BLOCK 20: síntese de marcadores
  (cid,20,121,'multiple_choice','[TOEFL Writing] Which paragraph BEST uses discourse markers for coherence?','Urbanization has accelerated in recent decades. Consequently, infrastructure in many cities is under severe strain. Furthermore, air quality has deteriorated significantly in rapidly growing metropolitan areas. That said, some cities have successfully managed growth through targeted investment in public transport. In conclusion, managed urbanization is both necessary and possible.','["Urbanization has accelerated. Also it has problems. So infrastructure is strained. But some cities do well.","Urbanization has accelerated in recent decades. Consequently, infrastructure in many cities is under severe strain. Furthermore, air quality has deteriorated significantly in rapidly growing metropolitan areas. That said, some cities have successfully managed growth through targeted investment in public transport. In conclusion, managed urbanization is both necessary and possible.","Urbanization accelerated. But problems exist. Furthermore so infrastructure suffers. However, in conclusion, it can be managed.","Urbanization is a problem; so cities have issues; and furthermore pollution; in conclusion manage it."]','Correctly uses: Consequently (cause-effect), Furthermore (addition), That said (concession), In conclusion (summary).','hard'),
  (cid,20,122,'production','[TOEFL Writing — Capstone] Write a 250-word TOEFL Independent essay on: "Do you agree that technology has done more harm than good?" Structure your essay with appropriate discourse markers for: introduction framing, each body paragraph (addition + contrast), concession, attribution, hedging, and conclusion. Every discourse marker must be used correctly and punctuated appropriately.','',NULL,'It is widely acknowledged that technology has transformed virtually every aspect of modern life. However, the question of whether these transformations have been overwhelmingly positive or harmful remains contested. In this essay, it will be argued that, on balance, technology has generated more benefits than drawbacks, provided it is used responsibly. Firstly, technology has dramatically expanded access to information and education. As noted by UNESCO, internet access has enabled millions of learners in developing nations to access world-class educational content. Furthermore, medical technology has significantly extended life expectancy and quality of life across the globe. Admittedly, technology has also created new risks. Social media, for instance, has been linked to rising rates of anxiety and depression among adolescents. Moreover, the automation of manufacturing has displaced millions of workers. That said, it may be argued that these challenges reflect how technology is governed rather than its inherent nature. Consequently, it would appear that the solution lies in smarter regulation, not in limiting innovation. In conclusion, while technology has undoubtedly created new social challenges, its capacity to solve problems — from climate change to disease — suggests that its overall contribution to human well-being has been and will continue to be positive, provided societies invest in ethical governance frameworks.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
